function [f, c] = st_focal(fov, n)
%ST_FOCAL  The focal length [px] and the principal point (1-based) of a detector of n pixels a side over a field of half-angle fov.
%   fov: real[1] (passed a plain number)
%   n: int (passed a whole number)
%   returns f: real[1] (passed a plain number)
%   returns c: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    f = 0;
    c = 0;
    nf = n;
    f = ((nf / 2) / tan(fov));
    c = ((nf + 1) / 2);
end
